**完整答案：可执行的循环数组 2-路插入排序**

d 中的有序段用 first 和 last 表示；逻辑第 $j$ 项位于 d[(first+j)%n]。二分查找采用 upper_bound，即新记录插在所有相等键之后，从而保持稳定。

~~~~c
static int at(int first, int off, int n) { return (first + off) % n; }
static int dec(int x, int n) { return (x + n - 1) % n; }
static int inc(int x, int n) { return (x + 1) % n; }

/* 返回逻辑有序段中第一个 key>x.key 的位置，范围 0..len。 */
static int UpperBound(Record d[], int first, int len, int n, Record x) {
    int lo = 0, hi = len;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (d[at(first, mid, n)].key <= x.key) lo = mid + 1;
        else                                    hi = mid;
    }
    return lo;
}

void TwoWayInsertSort(Record r[], Record d[], int n) {
    if (n <= 0) return;
    int first = 0, last = 0, len = 1;
    d[0] = r[0];

    for (int i = 1; i < n; ++i) {
        Record x = r[i];
        int pos = UpperBound(d, first, len, n, x);

        if (pos <= len - pos) {              /* 移动左侧较短前缀 */
            int newFirst = dec(first, n);
            for (int j = 0; j < pos; ++j)    /* 正向复制，覆盖安全 */
                d[at(newFirst, j, n)] = d[at(first, j, n)];
            first = newFirst;
            d[at(first, pos, n)] = x;
            /* last 不变 */
        } else {                             /* 移动右侧较短后缀 */
            int newLast = inc(last, n);
            for (int j = len - 1; j >= pos; --j) /* 反向复制 */
                d[at(first, j + 1, n)] = d[at(first, j, n)];
            last = newLast;
            d[at(first, pos, n)] = x;
        }
        ++len;
    }

    for (int j = 0; j < n; ++j)
        r[j] = d[at(first, j, n)];
}
~~~~

当 $x$ 小于首元时 pos=0，直接令 first 左移后写入；当 $x$ 大于等于末元时 pos=len，直接令 last 右移后写入。这两个边界不再错误地查找一个不存在的“最后一个 $\le x$”位置。

循环不变式是：处理完前 len 个输入后，从 first 起的 len 个循环单元非降序，且恰含这 len 个记录。插入时只把位置 pos 一侧整体挪一格，所以不变式保持。关键字比较 $O(n\log n)$，最坏移动 $O(n^2)$；除题目规定的第二数组 d[0..n-1] 外只用 $O(1)$ 空间。

