void BiBubbleSort(Record r[], int n) {
  int lo=0, hi=n-1, d=1;
  bool exchanged=true;
  while (lo<hi && exchanged) {
    exchanged=false;
    if (d==1) {
      for (int i=lo;i<hi;++i)
        if (r[i].key>r[i+1].key) {
          Record tmp=r[i]; r[i]=r[i+1]; r[i+1]=tmp;
          exchanged=true;
        }
      --hi;
    } else {
      for (int i=hi;i>lo;--i)
        if (r[i-1].key>r[i].key) {
          Record tmp=r[i]; r[i]=r[i-1]; r[i-1]=tmp;
          exchanged=true;
        }
      ++lo;
    }
    d=-d;
  }
}

变量 exchanged 只表示本趟是否发生真实交换；正向扫描后 hi 位置为最大键，反向扫描后 lo 位置为最小键。区间外始终有序，终止时全表有序。最坏 O(n^2)、空间 O(1)，已排序输入一趟结束。

